/** The keeper process: its config arrives on stdin; it answers `{ ok }` on stdout once it runs. */
export async function runKeeperProcess()                {
	const chunks           = [];
	for await (const chunk of process.stdin) chunks.push(chunk          );
	const report = (answer                         ) => process.stdout.write(`${JSON.stringify(answer)}\n`);
	let keeper               ;
	try {
		const config = JSON.parse(Buffer.concat(chunks).toString("utf8"))                ;
		keeper = new SessionKeeper(config, { onDone: () => process.exit(0) });
		await keeper.start();
	} catch (error) {
		report({ ok: false, error: error instanceof Error ? error.message : String(error) });
		process.exitCode = 1;
		return;
	}
	// Detached from any terminal; only an explicit SIGTERM (a shutdown) stops the session.
	process.on("SIGHUP", () => {});
	process.on("SIGINT", () => {});
	process.on("SIGTERM", () => keeper.stop());
	report({ ok: true, pid: process.pid });
}
